 	\[
 		\bigl\| (\Id - Q_{\mathrm{A}}) \ket{\Delta} \bigr\|^2
 		= \bigl\| (\Id - Q_{\mathrm{A}}) (\ket{\Delta} - \ket{\vartheta}) \bigr\|^2
 		\leq \bigl\| \ket{\Delta} - \ket{\vartheta} \bigr\|^2
