203	\section{The swap unitaries and the extraction of the Pauli group}
204	
205	\begin{definition}[The swap unitaries]\label{def:v-swap-unitary}
206		\uses{lem:qld-4-7, def:generalized-pauli, def:decoding-map}
207		Define the linear map
208		\[
209			V_{\mathrm{A}} = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \bigl(\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))\bigr)_{\mathrm{A}''}\;,
210		\]
211		where $\tau^X(\cdot)$ and $\tau^Z(\cdot)$ are the generalized Pauli observables acting on $(\C^q)^{\ot M}$; note that the argument of $\tau^X$ is $\mathrm{Dec}(g_Z)$ and the argument of $\tau^Z$ is $\mathrm{Dec}(g_X)$. The map $V_{\mathrm{B}}$, acting on registers $\mathrm{B}\mathrm{B}'\mathrm{B}''$, is defined analogously.
212	\end{definition}
213	
214	% In the source the following properties are established inline with the
215	% definition of the swap unitaries; they are recorded here as a lemma.
216	\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
217		\uses{def:v-swap-unitary, def:tilde-w-observables, def:tilde-m-measurement, def:generalized-pauli, def:indicator-vector, def:bracket}
218		The maps $V_{\mathrm{A}}$ and $V_{\mathrm{B}}$ of Definition~\ref{def:v-swap-unitary} are unitaries acting on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ and $\mathrm{B}\mathrm{B}'\mathrm{B}''$ respectively, and their conjugation action is exact, as follows. For all $W \in \{X,Z\}$, $j \in \{1,\ldots,t\}$, and $\tilde{u} \in \F_q^M$,
219		\begin{equation}\label{eq:v-swap-obs-conjugation}
220			V_{\mathrm{A}} \, \tilde{W}^j(\tilde{u}) \, V_{\mathrm{A}}^\dagger = \Id_{\mathrm{A}\mathrm{A}'} \ot \bigl( \tau^W(e_j \tilde{u}) \bigr)_{\mathrm{A}''}
221			\qquad \text{and} \qquad
222			V_{\mathrm{B}} \, \tilde{W}^j(\tilde{u}) \, V_{\mathrm{B}}^\dagger = \Id_{\mathrm{B}\mathrm{B}'} \ot \bigl( \tau^W(e_j \tilde{u}) \bigr)_{\mathrm{B}''}\;,
223		\end{equation}
224		and for all $W \in \{X,Z\}$, $u \in \F_q^m$, and $a \in \F_q$,
225		\begin{equation}\label{eq:qld-unitary-6}
226			V_{\mathrm{B}} \, \tilde{M}^{W,\mathrm{ind}_m(u)}_a \, V_{\mathrm{B}}^\dagger = \Id_{\mathrm{B}\mathrm{B}'} \ot (\tau^W_{[g_h(u)=a]})_{\mathrm{B}''}\;,
227			\qquad
228			\tau^W_{[g_h(u)=a]} = \sum_{h \,:\, g_h(u) = a} \tau^W_h\;,
229		\end{equation}
230		together with the analogous identity for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$.
231	\end{lemma}
232	\begin{proof}
233		\uses{lem:qld-4-7, lem:tildew-product-form, lem:twisted-commutation, def:v-swap-unitary, def:tilde-m-measurement, def:tau-dot-product-projector, def:indicator-vector, def:decoding-map, def:generalized-pauli}
234		Since the measurement $\{\hat{S}_{g_X,g_Z}\}$ is projective (Lemma~\ref{lem:qld-4-7}) and the $\tau^X, \tau^Z$ observables are self-inverse,
235		\[
236			V_{\mathrm{A}} V_{\mathrm{A}}^\dagger = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \Id_{\mathrm{A}''} = \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''}\;,
237		\]
238		and the same computation gives $V_{\mathrm{A}}^\dagger V_{\mathrm{A}} = \Id$, so $V_{\mathrm{A}}$ is unitary; likewise $V_{\mathrm{B}}$. For \eqref{eq:v-swap-obs-conjugation}, conjugate the product form \eqref{eq:tildewj-product-form} of $\tilde{W}^j(\tilde{u})$ (Lemma~\ref{lem:tildew-product-form}): by the orthogonality of the projectors $\hat{S}_{g_X,g_Z}$, only the diagonal terms survive, and the twisted commutation relation (Lemma~\ref{lem:twisted-commutation})
239		\[
240			\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X)) \, \tau^W(e_j \tilde{u}) = (-1)^{\tr( e_j(\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \tau^W(e_j \tilde{u}) \, \tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))
241		\]
242		cancels the sign $(-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))}$ term by term, leaving $\sum_{g_X,g_Z} \hat{S}_{g_X,g_Z} \ot \tau^W(e_j \tilde{u}) = \Id \ot \tau^W(e_j \tilde{u})$. For \eqref{eq:qld-unitary-6}, expand $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ by \eqref{eq:tilde_M} and \eqref{eq:def-tauwu}; by the orthogonality of the $\hat{S}_{g_X,g_Z}$, conjugation replaces, in the term of $\hat{S}^W_g$, each projector $\tau^W_h$ by $\tau^W_{h + \mathrm{Dec}(g)}$, using the identities $\tau^X(s)\, \tau^Z_h \,\tau^X(s)^\dagger = \tau^Z_{h+s}$ and $\tau^Z(s)\, \tau^X_h\, \tau^Z(s)^\dagger = \tau^X_{h+s}$. Substituting $h' = h + \mathrm{Dec}(g)$ turns the constraint $h \cdot \mathrm{ind}_m(u) = (\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)) - a$ into $h' \cdot \mathrm{ind}_m(u) = -a = a$, since $\F_q$ has characteristic $2$; the quantity $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ cancels exactly, so no relation between it and $g(u)$ is used (Remark~\ref{rem:qld-decoding-identity}). Since $h' \cdot \mathrm{ind}_m(u) = g_{h'}(u)$ \eqref{eq:low-degree-encoding-definition}, summing over $g$ gives \eqref{eq:qld-unitary-6}; the computation for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ is identical.
243	\end{proof}
